(function(){
  var m=document.getElementById('cmMin'),d=document.getElementById('cmDays'),w=document.getElementById('cmWeeks');
  var ow=document.getElementById('cmWeek'),ot=document.getElementById('cmTotal'),note=document.getElementById('cmNote');
  function n(el,lo,hi){var v=parseFloat(el.value);if(!isFinite(v))return null;if(v<lo||v>hi)return null;return v;}
  function calc(){
    var mi=n(m,1,240),dd=n(d,1,6),wk=n(w,1,52);
    if(mi===null||dd===null||wk===null){ow.textContent='—';ot.textContent='—';note.textContent='Fill in all three boxes to see your totals.';return;}
    var perWeek=(mi*2*dd)/60, total=perWeek*wk;
    ow.textContent=(Math.round(perWeek*10)/10)+'';
    ot.textContent=Math.round(total)+'';
    var msg='That is your real number. Sit with it for a minute before you decide.';
    if(perWeek<3) msg='That is a manageable week of driving for most people.';
    else if(perWeek<6) msg='Doable, but plan it — fuel, childcare and the drive home when you are tired.';
    else if(perWeek<10) msg='That is a serious commitment. Carpooling or the self-paced online program are both worth a real look.';
    else msg='At that much windshield time, we would genuinely rather talk with you about the online program first.';
    note.textContent=msg;
  }
  [m,d,w].forEach(function(el){el.addEventListener('input',calc);});calc();
})();
